def count_by_tag(notes):
    tag_counts = {}
    for note in notes:
        tags = note.get('tags', [])
        for tag in tags:
            tag_counts[tag] = tag_counts.get(tag, 0) + 1
    return tag_counts

# Example usage:
if __name__ == '__main__':
    notes = [
        {'title': 'Note 1', 'tags': ['work', 'urgent']},
        {'title': 'Note 2', 'tags': ['work', 'personal']},
        {'title': 'Note 3', 'tags': ['personal']}
    ]
    print(count_by_tag(notes))

